/**
 * @method
 * @name ndax#fetchStatus
 * @description the latest known information on the availability of the exchange API
 * @see https://apidoc.ndax.io/#ping
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [status structure]{@link https://docs.ccxt.com/?id=exchange-status-structure}
 */
func (this *Ndax) FetchStatusAsync(optionalArgs ...any) <-chan AsyncResult[Status] {
	ch := make(chan AsyncResult[Status], 1)
	go this.fetchStatusBody(ch, optionalArgs...)
	return ch
}
func (this *Ndax) fetchStatusBody(ch chan AsyncResult[Status], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.PublicGetPing(params)
	if r.Err != nil {
		panic(r.Err)
	}
	response := r.Raw
	//
	//     {
	//         "msg":"PONG"
	//     }
	//
	var message *string = this.SafeString(response, "msg")

	ch <- AsyncResult[Status]{Value: StatusFromMap(map[string]any{
		"status": func() string {
			if message != nil && *message == "PONG" {
				return "ok"
			}
			return "error"
		}(),
		"updated": nil,
		"eta":     nil,
		"url":     nil,
		"info":    response,
	})}
	return nil
}

/**
 * @method
 * @name ndax#signIn
 * @description sign in, must be called prior to using other authenticated methods
 * @see https://apidoc.ndax.io/#authenticate2fa
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns response from exchange
 */
func (this *Ndax) SignInAsync(optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.signInBody(ch, optionalArgs...)
	return ch
}
func (this *Ndax) signInBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()
	if (this.Login == nil) || (this.Password == "") {
		panic(AuthenticationError(this.Id + " signIn() requires exchange.login, exchange.password"))
	}
	var request map[string]any = map[string]any{
		"grant_type": "client_credentials",
	}

	r := <-this.PublicGetAuthenticate(this.Extend(request, params))
	if r.Err != nil {
		panic(r.Err)
	}
	response := r.Raw
	//
	//     {
	//         "Authenticated":true,
	//         "Requires2FA":true,
	//         "AuthType":"Google",
	//         "AddtlInfo":"",
	//         "Pending2FaToken": "6f5c4e66-f3ee-493e-9227-31cc0583b55f"
	//     }
	//
	var sessionToken *string = this.SafeString(response, "SessionToken")
	if sessionToken != nil {
		this.Options["sessionToken"] = DerefScalar(sessionToken)

		ch <- AsyncResult[any]{Value: response}
		return nil
	}
	var pending2faToken *string = this.SafeString(response, "Pending2FaToken")
	if pending2faToken != nil {
		if this.Twofa == nil {
			panic(AuthenticationError(this.Id + " signIn() requires exchange.twofa credentials"))
		}
		this.Options["pending2faToken"] = DerefScalar(pending2faToken)
		request = map[string]any{
			"Code": Totp(this.Twofa),
		}

		r1 := <-this.PublicGetAuthenticate2FA(this.Extend(request, params))
		if r1.Err != nil {
			panic(r1.Err)
		}
		responseInner := r1.Raw
		//
		//     {
		//         "Authenticated": true,
		//         "UserId":57764,
		//         "SessionToken":"4a2a5857-c4e5-4fac-b09e-2c4c30b591a0"
		//     }
		//
		sessionToken = this.SafeString(responseInner, "SessionToken")
		this.Options["sessionToken"] = DerefScalar(sessionToken)

		ch <- AsyncResult[any]{Value: responseInner}
		return nil
	}

	ch <- AsyncResult[any]{Value: response}
	return nil
}

