func (this *Ndax) ParseCurrency(rawCurrency any) map[string]any {
	var id *string = this.SafeString(rawCurrency, "ProductId")
	var code *string = this.SafeCurrencyCode(this.SafeString(rawCurrency, "Product"))
	var ProductType *string = this.SafeString(rawCurrency, "ProductType")
	var typeVar string = "crypto"
	if ProductType != nil && *ProductType == "NationalCurrency" {
		typeVar = "fiat"
	}
	if ProductType != nil && *ProductType == "Unknown" {
		// such currency is just a blanket entry
		typeVar = "other"
	}
	return this.SafeCurrencyStructure(map[string]any{
		"id":        id,
		"name":      this.SafeString(rawCurrency, "ProductFullName"),
		"code":      code,
		"type":      typeVar,
		"precision": this.SafeNumber(rawCurrency, "TickSize"),
		"info":      rawCurrency,
		"active":    (!(*this.SafeBool(rawCurrency, "IsDisabled", false))),
		"deposit":   this.SafeBool(rawCurrency, "DepositEnabled"),
		"withdraw":  this.SafeBool(rawCurrency, "WithdrawEnabled"),
		"fee":       nil,
		"limits": map[string]any{
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"withdraw": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"networks": map[string]any{},
		"margin":   this.SafeBool(rawCurrency, "MarginEnabled"),
	})
}

