func (this *Ndax) ParseMarket(market any) map[string]any {
	var id *string = this.SafeString(market, "InstrumentId")
	// const lowercaseId = this.safeStringLower (market, 'symbol');
	var baseId *string = this.SafeString(market, "Product1")
	var quoteId *string = this.SafeString(market, "Product2")
	var base *string = this.SafeCurrencyCode(this.SafeString(market, "Product1Symbol"))
	var quote *string = this.SafeCurrencyCode(this.SafeString(market, "Product2Symbol"))
	if (base == nil) || (quote == nil) {
		return nil
	}
	var sessionStatus *string = this.SafeString(market, "SessionStatus")
	var isDisable *bool = this.SafeBool(market, "IsDisable")
	var sessionRunning bool = (sessionStatus != nil && *sessionStatus == "Running")
	return this.SafeMarketStructure(map[string]any{
		"id":             id,
		"symbol":         *base + "/" + *quote,
		"base":           base,
		"quote":          quote,
		"settle":         nil,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       nil,
		"type":           "spot",
		"spot":           true,
		"margin":         false,
		"swap":           false,
		"future":         false,
		"option":         false,
		"active":         (sessionRunning && (isDisable == nil || *isDisable != true)),
		"contract":       false,
		"linear":         nil,
		"inverse":        nil,
		"contractSize":   nil,
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": this.SafeNumber(market, "QuantityIncrement"),
			"price":  this.SafeNumber(market, "PriceIncrement"),
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": this.SafeNumber(market, "MinimumQuantity"),
				"max": nil,
			},
			"price": map[string]any{
				"min": this.SafeNumber(market, "MinimumPrice"),
				"max": nil,
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"created": nil,
		"info":    market,
	})
}
func (this *Ndax) ParseOrderBook(orderbook any, symbol any, optionalArgs ...any) map[string]any {
	timestamp := GetArg(optionalArgs, 0, nil)
	_ = timestamp
	var bidsKey string = GetArgString(optionalArgs, 1, "bids")
	_ = bidsKey
	var asksKey string = GetArgString(optionalArgs, 2, "asks")
	_ = asksKey
	priceKey := GetArg(optionalArgs, 3, 6)
	_ = priceKey
	amountKey := GetArg(optionalArgs, 4, 8)
	_ = amountKey
	countOrIdKey := GetArg(optionalArgs, 5, 2)
	_ = countOrIdKey
	var nonce *int64 = this.SafeInteger(this.SafeList(orderbook, 0), 0)
	var latestTimestamp *int64 = this.SafeInteger([]any{timestamp}, 0)
	var result map[string]any = map[string]any{
		"symbol":    symbol,
		"bids":      []any{},
		"asks":      []any{},
		"timestamp": nil,
		"datetime":  nil,
		"nonce":     nil,
	}
	var bids []any = []any{}
	var asks []any = []any{}
	for i := 0; i < GetArrayLength(orderbook); i++ {
		var level any = this.SafeValue(orderbook, i)
		var newTimestamp *int64 = this.SafeInteger(level, 2)
		if (newTimestamp != nil) && ((latestTimestamp == nil) || (*newTimestamp > *latestTimestamp)) {
			latestTimestamp = newTimestamp
		}
		var newNonce *int64 = this.SafeInteger(level, 0)
		if (newNonce != nil) && ((nonce == nil) || (*newNonce > *nonce)) {
			nonce = newNonce
		}
		var bidask []any = this.ParseOrderBookBidAsk(level, priceKey, amountKey)
		var levelSide *int64 = this.SafeInteger(level, 9)
		if (levelSide != nil) && (levelSide == nil || *levelSide != 0) {
			asks = append(asks, bidask)
		} else {
			bids = append(bids, bidask)
		}
	}
	result["bids"] = this.SortBy(bids, 0, true)
	result["asks"] = this.SortBy(asks, 0)
	result["timestamp"] = latestTimestamp
	result["datetime"] = this.Iso8601(latestTimestamp)
	result["nonce"] = nonce
	return result
}

