func (this *Ndax) fetchOrderBookBody(ch chan AsyncResult[OrderBook], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var omsId *int64 = this.SafeInteger(this.Options, "omsId", 1)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var limitValue int64 = func() int64 {
		if limit == nil {
			return 100
		}
		return *limit
	}() // default 100
	var request map[string]any = map[string]any{
		"omsId":        omsId,
		"InstrumentId": market["id"],
		"Depth":        limitValue,
	}

	listEp1039 := <-this.PublicGetGetL2Snapshot(this.Extend(request, params))
	if listEp1039.Err != nil {
		panic(listEp1039.Err)
	}
	var response []any = listEp1039.Value

	//
	//     [
	//         [
	//             0,   // 0 MDUpdateId
	//             1,   // 1 Number of Unique Accounts
	//             123, // 2 ActionDateTime in Posix format X 1000
	//             0,   // 3 ActionType 0 (New), 1 (Update), 2(Delete)
	//             0.0, // 4 LastTradePrice
	//             0,   // 5 Number of Orders
	//             0.0, // 6 Price
	//             0,   // 7 ProductPairCode
	//             0.0, // 8 Quantity
	//             0,   // 9 Side
	//         ],
	//         [97244115,1,1607456142963,0,19069.32,1,19069.31,8,0.140095,0],
	//         [97244115,0,1607456142963,0,19069.32,1,19068.64,8,0.0055,0],
	//         [97244115,0,1607456142963,0,19069.32,1,19068.26,8,0.021291,0],
	//         [97244115,1,1607456142964,0,19069.32,1,19069.32,8,0.099636,1],
	//         [97244115,0,1607456142964,0,19069.32,1,19069.98,8,0.1,1],
	//         [97244115,0,1607456142964,0,19069.32,1,19069.99,8,0.141604,1],
	//     ]
	//
	ch <- AsyncResult[OrderBook]{Value: OrderBookFromMap(this.ParseOrderBook(response, symbol))}
	return nil
}
func (this *Ndax) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	// fetchTicker
	//
	//     {
	//         "OMSId":1,
	//         "InstrumentId":8,
	//         "BestBid":19069.31,
	//         "BestOffer":19069.32,
	//         "LastTradedPx":19069.32,
	//         "LastTradedQty":0.0001,
	//         "LastTradeTime":1607040406424,
	//         "SessionOpen":19069.32,
	//         "SessionHigh":19069.32,
	//         "SessionLow":19069.32,
	//         "SessionClose":19069.32,
	//         "Volume":0.0001,
	//         "CurrentDayVolume":0.0001,
	//         "CurrentDayNotional":1.906932,
	//         "CurrentDayNumTrades":1,
	//         "CurrentDayPxChange":0.00,
	//         "Rolling24HrVolume":0.000000000000000000000000000,
	//         "Rolling24HrNotional":0.00000000000000000000000,
	//         "Rolling24NumTrades":0,
	//         "Rolling24HrPxChange":0,
	//         "TimeStamp":"1607040406425",
	//         "BidQty":0,
	//         "AskQty":0,
	//         "BidOrderCt":0,
	//         "AskOrderCt":0,
	//         "Rolling24HrPxChangePercent":0,
	//     }
	//
	// fetchTickers
	//
	//     {
	//         "trading_pairs":"BTC_CAD",
	//         "last_price":75925.37,
	//         "lowest_ask":75926.63,
	//         "highest_bid":66.435340000000000000000000000,
	//         "base_volume":75774.93,
	//         "quote_volume":5112197.7830825000000000000000,
	//         "price_change_percent_24h":-5.3894893561980828521107542600,
	//         "highest_price_24h":79813.51,
	//         "lowest_price_24h":73700.01
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(ticker, "TimeStamp")
	var marketId *string = this.SafeString(ticker, "InstrumentId")
	if marketId == nil {
		marketId = this.SafeString(ticker, "trading_pairs")
	}
	var marketResolved map[string]any = this.SafeMarket(marketId, market, "_")
	var symbol *string = this.SafeSymbol(marketId, marketResolved)
	var last *string = this.SafeString2(ticker, "LastTradedPx", "last_price")
	var percentage *string = this.SafeString2(ticker, "Rolling24HrPxChangePercent", "price_change_percent_24h")
	var change *string = this.SafeString(ticker, "Rolling24HrPxChange")
	var open *string = this.SafeString(ticker, "SessionOpen")
	var baseVolume *string = this.SafeString2(ticker, "Rolling24HrVolume", "base_volume")
	var quoteVolume *string = this.SafeString2(ticker, "Rolling24HrNotional", "quote_volume")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString2(ticker, "SessionHigh", "highest_price_24h"),
		"low":           this.SafeString2(ticker, "SessionLow", "lowest_price_24h"),
		"bid":           this.SafeString2(ticker, "BestBid", "highest_bid"),
		"bidVolume":     nil,
		"ask":           this.SafeString2(ticker, "BestOffer", "lowest_ask"),
		"askVolume":     nil,
		"vwap":          nil,
		"open":          open,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        change,
		"percentage":    percentage,
		"average":       nil,
		"baseVolume":    baseVolume,
		"quoteVolume":   quoteVolume,
		"info":          ticker,
	}, marketResolved)
}

