func (this *Ndax) fetchAccountsBody(ch chan AsyncResult[[]Account], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if (this.Login == nil) || (this.Login == "") {
		panic(AuthenticationError(this.Id + " fetchAccounts() requires exchange.login email credential"))
	}
	var omsId *int64 = this.SafeInteger(this.Options, "omsId", 1)
	this.CheckRequiredCredentials()
	var request map[string]any = map[string]any{
		"omsId":    omsId,
		"UserId":   this.Uid,
		"UserName": this.Login,
	}

	listEp1611 := <-this.PrivateGetGetUserAccounts(this.Extend(request, params))
	if listEp1611.Err != nil {
		panic(listEp1611.Err)
	}
	var response []any = listEp1611.Value
	//
	//     [ 449 ] // comma-separated list of account ids
	//
	var result []any = []any{}
	for i := 0; i < len(response); i++ {
		var accountId *string = this.SafeString(response, i)
		result = append(result, map[string]any{
			"id":       accountId,
			"type":     nil,
			"currency": nil,
			"info":     accountId,
		})
	}

	ch <- AsyncResult[[]Account]{Value: AccountsFromList(result)}
	return nil
}
func (this *Ndax) ParseBalanceList(response any) map[string]any {
	var result map[string]any = map[string]any{
		"info":      response,
		"timestamp": nil,
		"datetime":  nil,
	}
	for i := 0; i < GetArrayLength(response); i++ {
		var balance map[string]any = SafeMapTyped(response, i)
		var currencyId *string = this.SafeString(balance, "ProductId")
		if (currencyId != nil) && (this.Currencies_by_id() != nil) && (InOp(this.Currencies_by_id(), currencyId)) {
			var code *string = this.SafeCurrencyCode(currencyId)
			var account map[string]any = this.Account()
			account["total"] = this.SafeString(balance, "Amount")
			account["used"] = this.SafeString(balance, "Hold")
			if code != nil {
				result[*code] = account
			}
		}
	}
	return this.SafeBalance(result).(map[string]any)
}

