func (this *Ndax) fetchWithdrawalsBody(ch chan AsyncResult[[]Transaction], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	var omsId *int64 = this.SafeInteger(this.Options, "omsId", 1)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	r1 := <-this.LoadAccountsAsync()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var defaultAccountId *int64 = this.SafeInteger2(this.Options, "accountId", "AccountId", this.ParseToInt(this.SafeString(this.SafeDict(this.Accounts, 0), "id")))
	var accountId *int64 = this.SafeInteger2(params, "accountId", "AccountId", defaultAccountId)
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"accountId", "AccountId"})
	var currency map[string]any = nil
	if code != nil {
		currency = this.Currency(code)
	}
	var request map[string]any = map[string]any{
		"omsId":     omsId,
		"AccountId": accountId,
	}

	listEp3040 := <-this.PrivateGetGetWithdraws(this.Extend(request, paramsOmitted))
	if listEp3040.Err != nil {
		panic(listEp3040.Err)
	}
	var response []any = listEp3040.Value

	//
	//     [
	//         {
	//             "Amount": 0.0,
	//             "FeeAmount": 0.0,
	//             "NotionalValue": 0.0,
	//             "WithdrawId": 0,
	//             "AssetManagerId": 0,
	//             "AccountId": 0,
	//             "AssetId": 0,
	//             "TemplateForm": "{\"TemplateType\": \"TetherRPCWithdraw\",\"Comment\": \"TestWithdraw\",\"ExternalAddress\": \"ms6C3pKAAr8gRCcnVebs8VRkVrjcvqNYv3\"}",
	//             "TemplateFormType": "TetherRPCWithdraw",
	//             "omsId": 0,
	//             "TicketStatus": 0,
	//             "TicketNumber": 0,
	//             "WithdrawTransactionDetails": "",
	//             "WithdrawType": "",
	//             "WithdrawCode": "490b4fa3-53fc-44f4-bd29-7e16be86fba3",
	//             "AssetType": 0,
	//             "Reaccepted": true,
	//             "NotionalProductId": 0
	//         },
	//     ]
	//
	ch <- AsyncResult[[]Transaction]{Value: TransactionsFromList(this.ParseTransactions(response, currency, since, limit))}
	return nil
}
func (this *Ndax) ParseTransactionStatusByType(optionalArgs ...any) *string {
	var status *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = status
	var typeVar *string = GetArgStringPtr(optionalArgs, 1, nil)
	_ = typeVar
	var statusesByType map[string]any = map[string]any{
		"deposit": map[string]any{
			"New":              "pending",
			"AdminProcessing":  "pending",
			"Accepted":         "pending",
			"Rejected":         "rejected",
			"SystemProcessing": "pending",
			"FullyProcessed":   "ok",
			"Failed":           "failed",
			"Pending":          "pending",
			"Confirmed":        "pending",
			"AmlProcessing":    "pending",
			"AmlAccepted":      "pending",
			"AmlRejected":      "rejected",
			"AmlFailed":        "failed",
			"LimitsAccepted":   "pending",
			"LimitsRejected":   "rejected",
		},
		"withdrawal": map[string]any{
			"New":               "pending",
			"AdminProcessing":   "pending",
			"Accepted":          "pending",
			"Rejected":          "rejected",
			"SystemProcessing":  "pending",
			"FullyProcessed":    "ok",
			"Failed":            "failed",
			"Pending":           "pending",
			"Pending2Fa":        "pending",
			"AutoAccepted":      "pending",
			"Delayed":           "pending",
			"UserCanceled":      "canceled",
			"AdminCanceled":     "canceled",
			"AmlProcessing":     "pending",
			"AmlAccepted":       "pending",
			"AmlRejected":       "rejected",
			"AmlFailed":         "failed",
			"LimitsAccepted":    "pending",
			"LimitsRejected":    "rejected",
			"Submitted":         "pending",
			"Confirmed":         "pending",
			"ManuallyConfirmed": "pending",
			"Confirmed2Fa":      "pending",
		},
	}
	var statuses any = func() any {
		if typeVar == nil {
			return map[string]any{}
		}
		return this.SafeDict(statusesByType, typeVar, map[string]any{})
	}()
	if status == nil {
		return nil
	}
	return this.SafeString(statuses, status, status)
}
func (this *Ndax) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	// fetchDeposits
	//
	//    {
	//        "OMSId": 1,
	//        "DepositId": 44,
	//        "AccountId": 449,
	//        "SubAccountId": 0,
	//        "ProductId": 4,
	//        "Amount": 200.00000000000000000000000000,
	//        "LastUpdateTimeStamp": 637431291261187806,
	//        "ProductType": "CryptoCurrency",
	//        "TicketStatus": "FullyProcessed",
	//        "DepositInfo": "{
	//            "AccountProviderId":42,
	//            "AccountProviderName":"USDT_BSC",
	//            "TXId":"0x3879b02632c69482646409e991149290bc9a58e4603be63c7c2c90a843f45d2b",
	//            "FromAddress":"0x8894E0a0c962CB723c1976a4421c95949bE2D4E3",
	//            "ToAddress":"0x5428EcEB1F7Ee058f64158589e27D087149230CB"
	//        }",
	//        "DepositCode": "ab0e23d5-a9ce-4d94-865f-9ab464fb1de3",
	//        "TicketNumber": 71,
	//        "NotionalProductId": 13,
	//        "NotionalValue": 200.00000000000000000000000000,
	//        "FeeAmount": 0.0000000000000000000000000000,
	//     }
	//
	// fetchWithdrawals
	//
	//     {
	//         "Amount": 0.0,
	//         "FeeAmount": 0.0,
	//         "NotionalValue": 0.0,
	//         "WithdrawId": 0,
	//         "AssetManagerId": 0,
	//         "AccountId": 0,
	//         "AssetId": 0,
	//         "TemplateForm": "{\"TemplateType\": \"TetherRPCWithdraw\",\"Comment\": \"TestWithdraw\",\"ExternalAddress\": \"ms6C3pKAAr8gRCcnVebs8VRkVrjcvqNYv3\"}",
	//         "TemplateFormType": "TetherRPCWithdraw",
	//         "omsId": 0,
	//         "TicketStatus": 0,
	//         "TicketNumber": 0,
	//         "WithdrawTransactionDetails": "",
	//         "WithdrawType": "",
	//         "WithdrawCode": "490b4fa3-53fc-44f4-bd29-7e16be86fba3",
	//         "AssetType": 0,
	//         "Reaccepted": true,
	//         "NotionalProductId": 0
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var id *string = this.SafeString(transaction, "DepositId")
	var currencyId *string = this.SafeString(transaction, "ProductId")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var typeVar any = nil
	if id != nil {
		typeVar = "deposit"
	} else {
		id = this.SafeString(transaction, "WithdrawId")
		if id != nil {
			typeVar = "withdrawal"
		}
	}
	var templateForm any = this.ParseJson(this.SafeValue2(transaction, "TemplateForm", "DepositInfo"))
	var updated *int64 = this.SafeInteger(transaction, "LastUpdateTimeStamp")
	if templateForm != nil {
		updated = this.SafeInteger(templateForm, "LastUpdated", updated)
	}
	var address *string = this.SafeString2(templateForm, "ExternalAddress", "ToAddress")
	var timestamp *int64 = this.SafeInteger(templateForm, "TimeSubmitted")
	var feeCost *float64 = this.SafeNumber(transaction, "FeeAmount")
	var transactionStatus *string = this.SafeString(transaction, "TicketStatus")
	var fee map[string]any = map[string]any{}
	if feeCost != nil {
		fee = map[string]any{
			"currency": code,
			"cost":     feeCost,
		}
	}
	return TransactionFromMap(map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        this.SafeString2(templateForm, "TxId", "TXId"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"address":     address,
		"addressTo":   address,
		"addressFrom": this.SafeString(templateForm, "FromAddress"),
		"tag":         nil,
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      this.SafeNumber(transaction, "Amount"),
		"currency":    code,
		"status":      this.ParseTransactionStatusByType(transactionStatus, typeVar),
		"updated":     updated,
		"fee":         fee,
		"internal":    nil,
		"comment":     nil,
		"network":     nil,
	})
}

/**
 * @method
 * @name ndax#withdraw
 * @description make a withdrawal
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.tag] memo / destination tag, required for currencies in options['withdrawTagRequiredCurrencies']
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Ndax) WithdrawAsync(code string, amount any, address any, optionalArgs ...any) <-chan AsyncResult[Transaction] {
	ch := make(chan AsyncResult[Transaction], 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Ndax) withdrawBody(ch chan AsyncResult[Transaction], code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var tagWithdrawTag *string = this.SafeString(params, "tag")
	var paramsWithdrawTag map[string]any = this.OmitDict(params, "tag")
	// this method required login, password and twofa key
	var sessionToken *string = this.SafeString(this.Options, "sessionToken")
	if sessionToken == nil {
		panic(AuthenticationError(this.Id + " call signIn() method to obtain a session token"))
	}
	if this.Twofa == nil {
		panic(AuthenticationError(this.Id + " withdraw() requires exchange.twofa credentials"))
	}
	this.CheckAddress(address, code, tagWithdrawTag)
	var omsId *int64 = this.SafeInteger(this.Options, "omsId", 1)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	r1 := <-this.LoadAccountsAsync()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var defaultAccountId *int64 = this.SafeInteger2(this.Options, "accountId", "AccountId", this.ParseToInt(this.SafeString(this.SafeDict(this.Accounts, 0), "id")))
	var accountId *int64 = this.SafeInteger2(paramsWithdrawTag, "accountId", "AccountId", defaultAccountId)
	var paramsOmitted map[string]any = this.OmitDict(paramsWithdrawTag, []any{"accountId", "AccountId"})
	var currency map[string]any = this.Currency(code)
	var withdrawTemplateTypesRequest map[string]any = map[string]any{
		"omsId":     omsId,
		"AccountId": accountId,
		"ProductId": currency["id"],
	}

	r2 := <-this.PrivateGetGetWithdrawTemplateTypes(withdrawTemplateTypesRequest)
	if r2.Err != nil {
		panic(r2.Err)
	}
	var withdrawTemplateTypesResponse map[string]any = r2.Value
	//
	//     {
	//         "result": true,
	//         "errormsg": null,
	//         "statuscode": "0",
	//         "TemplateTypes": [
	//             { AccountProviderId: "14", TemplateName: "ToExternalBitcoinAddress", AccountProviderName: "BitgoRPC-BTC" },
	//             { AccountProviderId: "20", TemplateName: "ToExternalBitcoinAddress", AccountProviderName: "TrezorBTC" },
	//             { AccountProviderId: "31", TemplateName: "BTC", AccountProviderName: "BTC Fireblocks 1" }
	//         ]
	//     }
	//
	var templateTypes []any = SafeListTyped(withdrawTemplateTypesResponse, "TemplateTypes")
	var firstTemplateType map[string]any = SafeMapTyped(templateTypes, 0)
	if firstTemplateType == nil {
		panic(ExchangeError(this.Id + " withdraw() could not find a withdraw template type for " + currency["code"].(string)))
	}
	var templateName *string = this.SafeString(firstTemplateType, "TemplateName")
	var withdrawTemplateRequest map[string]any = map[string]any{
		"omsId":             omsId,
		"AccountId":         accountId,
		"ProductId":         currency["id"],
		"TemplateType":      templateName,
		"AccountProviderId": firstTemplateType["AccountProviderId"],
	}

	r3 := <-this.PrivateGetGetWithdrawTemplate(withdrawTemplateRequest)
	if r3.Err != nil {
		panic(r3.Err)
	}
	var withdrawTemplateResponse map[string]any = r3.Value
	//
	//     {
	//         "result": true,
	//         "errormsg": null,
	//         "statuscode": "0",
	//         "Template": "{\"TemplateType\":\"ToExternalBitcoinAddress\",\"Comment\":\"\",\"ExternalAddress\":\"\"}"
	//     }
	//
	var template *string = this.SafeString(withdrawTemplateResponse, "Template")
	if template == nil {
		panic(ExchangeError(this.Id + " withdraw() could not find a withdraw template for " + currency["code"].(string)))
	}
	var withdrawTemplate any = JsonParse(template)
	AddElementToObject(withdrawTemplate, "ExternalAddress", address)
	if tagWithdrawTag != nil {
		if InOp(withdrawTemplate, "Memo") {
			AddElementToObject(withdrawTemplate, "Memo", tagWithdrawTag)
		}
	}
	var withdrawPayload map[string]any = map[string]any{
		"omsId":        omsId,
		"AccountId":    accountId,
		"ProductId":    currency["id"],
		"TemplateForm": this.Json(withdrawTemplate),
		"TemplateType": templateName,
	}
	var withdrawRequest map[string]any = map[string]any{
		"TfaType": "Google",
		"TFaCode": Totp(this.Twofa),
		"Payload": this.Json(withdrawPayload),
	}

	r4 := <-this.PrivatePostCreateWithdrawTicket(this.DeepExtend(withdrawRequest, paramsOmitted))
	if r4.Err != nil {
		panic(r4.Err)
	}
	var response map[string]any = r4.Value

	ch <- AsyncResult[Transaction]{Value: this.ParseTransaction(response, currency)}
	return nil
}
func (this *Ndax) Nonce() int64 {
	return this.Milliseconds()
}
func (this *Ndax) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var apiName string = api[0]
	var bodySigned *string = nil
	var headersSigned any = nil
	var apiUrl *string = this.SafeString(this.Urls["api"], apiName)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url string = *apiUrl + "/" + this.ImplodeParams(path, params)
	var query any = this.Omit(params, this.ExtractParams(path))
	if apiName == "public" {
		if path == "Authenticate" {
			var auth any = Add(Add(this.Login, ":"), this.Password)
			var auth64 string = this.StringToBase64(auth)
			headersSigned = map[string]any{
				"Authorization": "Basic " + auth64,
			}
		} else if path == "Authenticate2FA" {
			var pending2faToken *string = this.SafeString(this.Options, "pending2faToken")
			if pending2faToken != nil {
				headersSigned = map[string]any{
					"Pending2FaToken": pending2faToken,
				}
				query = this.Omit(query, "pending2faToken")
			}
		}
		if queryMap, _ := query.(map[string]any); len(queryMap) > 0 {
			url += "?" + this.Urlencode(query)
		}
	} else if apiName == "private" {
		this.CheckRequiredCredentials()
		var sessionToken *string = this.SafeString(this.Options, "sessionToken")
		var isPost bool = (method == "POST")
		if sessionToken == nil {
			var nonce string = strconv.FormatInt(this.Nonce(), 10)
			var auth string = nonce + this.Uid + this.ApiKey
			var signature string = this.Hmac(this.Encode(auth), this.Encode(this.Secret), sha256)
			if isPost {
				headersSigned = map[string]any{
					"Nonce":        nonce,
					"APIKey":       this.ApiKey,
					"Signature":    signature,
					"UserId":       this.Uid,
					"Content-Type": "application/json",
				}
			} else {
				headersSigned = map[string]any{
					"Nonce":     nonce,
					"APIKey":    this.ApiKey,
					"Signature": signature,
					"UserId":    this.Uid,
				}
			}
		} else if isPost {
			headersSigned = map[string]any{
				"APToken":      sessionToken,
				"Content-Type": "application/json",
			}
		} else {
			headersSigned = map[string]any{
				"APToken": sessionToken,
			}
		}
		if isPost {
			jsonText := this.Json(query)
			bodySigned = &jsonText
		} else {
			if queryMap, _ := query.(map[string]any); len(queryMap) > 0 {
				url += "?" + this.Urlencode(query)
			}
		}
	}
	var headersResolved any = headersSigned
	var bodyResolved *string = bodySigned
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    bodyResolved,
		"headers": headersResolved,
	}
}
func (this *Ndax) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if code == 404 {
		panic(AuthenticationError(this.Id + " " + body))
	}
	if response == nil {
		return nil
	}
	//
	//     {"status":"Rejected","errormsg":"Not_Enough_Funds","errorcode":101}
	//     {"result":false,"errormsg":"Server Error","errorcode":102,"detail":null}
	//
	var message *string = this.SafeString(response, "errormsg")
	if (message != nil) && (message == nil || *message != "") {
		var feedback string = this.Id + " " + body
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], body, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewNdax(userConfig map[string]any) *Ndax {
	p := newNdax()
	p.Init(userConfig)
	return p
}

func (this *Ndax) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

